local function isMyKill(humanoid)
    -- Only explicit replicated attribution counts as a confirmed kill.
    local character=humanoid.Parent
    local function check(container)
        if not container then return false end
        for _,name in ipairs({'creator','Creator','killer','Killer','LastAttacker','lastAttacker'}) do
            local value=container:FindFirstChild(name)
            if value then
                if value:IsA('ObjectValue') and (value.Value==me or value.Value==me.Character) then return true end
                if value:IsA('StringValue') and (value.Value==me.Name or value.Value==tostring(me.UserId)) then return true end
                if value:IsA('IntValue') and value.Value==me.UserId then return true end
            end
            local ok,attribute=pcall(function() return container:GetAttribute(name) end)
            if ok and (attribute==me.UserId or attribute==me.Name or attribute==tostring(me.UserId)) then return true end
        end
        return false
    end
    return check(humanoid) or check(character)
end
-- Local-only kneeling effect. Works with standard R6 and R15 rigs,
-- independently of the victim's orientation at death.
local Debris=game:GetService('Debris')
local function showLocalKneel(h, savedCharacter)
    local character=savedCharacter or h.Parent
    if not character or not character:IsA('Model') then return end
    local root=character:FindFirstChild('HumanoidRootPart') or character.PrimaryPart
    if not root or not root:IsA('BasePart') then return end
    local rootPosition=root.Position
    local direction=Vector3.new(root.CFrame.LookVector.X,0,root.CFrame.LookVector.Z)
    if direction.Magnitude<0.01 then direction=Vector3.new(0,0,-1) end
    direction=direction.Unit

    local oldArchivable=character.Archivable
    character.Archivable=true
    local ok,ghost=pcall(function() return character:Clone() end)
    character.Archivable=oldArchivable
    if not ok or not ghost then return end
    ghost.Name='FOLIX_ClientOnlyKneel'
    for _,item in ipairs(ghost:GetDescendants()) do
        if item:IsA('BaseScript') or item:IsA('Sound') or item:IsA('Tool') or item:IsA('Animator') then
            item:Destroy()
        elseif item:IsA('BasePart') then
            item.Anchored=true
            item.CanCollide=false
            item.CanTouch=false
            item.CanQuery=false
            item.AssemblyLinearVelocity=Vector3.zero
            item.AssemblyAngularVelocity=Vector3.zero
        elseif item:IsA('Humanoid') then
            item.DisplayDistanceType=Enum.HumanoidDisplayDistanceType.None
            item.BreakJointsOnDeath=false
        elseif item:IsA('Motor6D') then
            item.Transform=CFrame.identity
        end
    end
    local rig=h.RigType
    for _,joint in ipairs(ghost:GetDescendants()) do
        if joint:IsA('Motor6D') then
            local name=joint.Name
            if rig==Enum.HumanoidRigType.R15 then
                if name=='RightHip' or name=='LeftHip' then
                    joint.C0=joint.C0*CFrame.Angles(math.rad(-75),0,0)
                elseif name=='RightKnee' or name=='LeftKnee' then
                    joint.C0=joint.C0*CFrame.Angles(math.rad(110),0,0)
                elseif name=='Waist' then
                    joint.C0=joint.C0*CFrame.Angles(math.rad(14),0,0)
                end
            else
                if name=='Right Hip' then
                    joint.C0=joint.C0*CFrame.Angles(math.rad(-95),0,math.rad(8))
                elseif name=='Left Hip' then
                    joint.C0=joint.C0*CFrame.Angles(math.rad(-95),0,math.rad(-8))
                end
            end
        end
    end
    ghost.Parent=Workspace
    -- Use an upright Y-only heading, never the fallen body's tilt.
    local upright=CFrame.lookAt(rootPosition,rootPosition+direction)
    local ghostRoot=ghost:FindFirstChild('HumanoidRootPart')
    if ghostRoot then
        local oldPivot=ghost:GetPivot()
        ghost:PivotTo(upright * ghostRoot.CFrame:ToObjectSpace(oldPivot))
    else
        ghost:PivotTo(upright)
    end
    -- Sit the knees close to the floor when a floor is present.
    local ray=Workspace:Raycast(rootPosition+Vector3.new(0,4,0),Vector3.new(0,-20,0))
    local baseline=ray and ray.Position.Y or (rootPosition.Y-3)
    local minY=math.huge
    for _,part in ipairs(ghost:GetDescendants()) do
        if part:IsA('BasePart') and part.Name~='HumanoidRootPart' then
            minY=math.min(minY,part.Position.Y-part.Size.Y/2)
        end
    end
    if minY<math.huge then
        ghost:PivotTo(ghost:GetPivot()+Vector3.new(0,baseline-minY+0.07,0))
    end
    Debris:AddItem(ghost,4)
end
-- TSB-focused local effects (players + training dummies).
-- Attribution without a server kill tag is heuristic, not authoritative.
local recentAttackAt=-100
local lastHitByModel=setmetatable({}, {__mode='k'})
local UIS=game:GetService('UserInputService')
local function attackInput(input,processed)
    if processed then return end
    local k=input.KeyCode
    if input.UserInputType==Enum.UserInputType.MouseButton1 or k==Enum.KeyCode.One or
       k==Enum.KeyCode.Two or k==Enum.KeyCode.Three or k==Enum.KeyCode.Four or
       k==Enum.KeyCode.Q or k==Enum.KeyCode.E or k==Enum.KeyCode.R or
       k==Enum.KeyCode.F then
       recentAttackAt=os.clock()
    end
end
table.insert(royalKillConnections,UIS.InputBegan:Connect(attackInput))
local function closeToMe(model,dist)
    local myRoot=me.Character and me.Character:FindFirstChild('HumanoidRootPart')
    local victimRoot=model and (model:FindFirstChild('HumanoidRootPart') or model:FindFirstChild('Torso') or model:FindFirstChild('UpperTorso'))
    return myRoot and victimRoot and (myRoot.Position-victimRoot.Position).Magnitude<=dist
end
local function recentTsbHit(model)
    local t=lastHitByModel[model]
    return t and os.clock()-t<=2.0 and closeToMe(model,24)
end
local function monitorRoyalHumanoid(h)
    if monitoredHumanoids[h] or not h:IsA('Humanoid') then return end
    local model=h.Parent
    if not model or not model:IsA('Model') or model==me.Character then return end
    monitoredHumanoids[h]=true
    local handled=false
    local cachedRig=nil
    local oldHealth=h.Health
    local connections={}
    local function watch(c)
        table.insert(connections,c)
        table.insert(royalKillConnections,c)
    end
    local function snapshot()
        if h.Health<=0 or not model.Parent then return end
        local old=model.Archivable
        model.Archivable=true
        local ok,copy=pcall(function() return model:Clone() end)
        model.Archivable=old
        if ok and copy then
            if cachedRig then cachedRig:Destroy() end
            cachedRig=copy
        end
    end
    snapshot()
    local function finish()
        if handled then return end
        if not (isMyKill(h) or recentTsbHit(model)) then return end
        handled=true
        playRoyalKillSound()
        local ok,err=pcall(showLocalKneel,h,cachedRig or model)
        if not ok then warn('[FOLIX/TSB] Visual:',err) end
        if cachedRig then cachedRig:Destroy();cachedRig=nil end
    end
    watch(h.HealthChanged:Connect(function(health)
        -- Record credible recent local damage; watching health alone is not proof of a kill.
        if health<oldHealth and health>0 and os.clock()-recentAttackAt<0.9 and closeToMe(model,18) then
            lastHitByModel[model]=os.clock()
            if not cachedRig then snapshot() end
        end
        oldHealth=health
        if health<=0 then
            finish()
            task.delay(0.25,finish)
            task.delay(0.8,finish)
        end
    end))
    watch(h.Died:Connect(function()
        finish()
        task.delay(0.2,finish)
        task.delay(0.7,finish)
    end))
    watch(model.AncestryChanged:Connect(function(_,parent)
        if not parent then
            -- TSB may despawn a dummy before Died is replicated.
            finish()
            task.delay(1,function()
                if cachedRig then cachedRig:Destroy();cachedRig=nil end
            end)
        end
    end))
end
-- Event-based discovery avoids repeatedly scanning the whole map during combat.
