    if obj:IsA('Humanoid') then monitorRoyalHumanoid(obj) end
end
table.insert(royalKillConnections,Workspace.DescendantAdded:Connect(function(obj)
    if obj:IsA('Humanoid') then monitorRoyalHumanoid(obj) end
