    task.spawn(function()
        local descendants=Workspace:GetDescendants()
        for i,inst in ipairs(descendants) do
            if not active or not npcEnabled or version~=npcResizeScanVersion then return end
            if inst:IsA('Model') then applyNpc(inst) end
