-- Premium is a cosmetic ROBLOX MAXIMKA badge for everyone (not a paid-access bypass).
CROWN_B64 = [[]]
crownAsset=nil
pcall(function()
    local assetFn=(type(getcustomasset)=='function' and getcustomasset)
        or (type(getsynasset)=='function' and getsynasset)
    if type(writefile)=='function' and assetFn then
        local data=(type(crypt)=='table' and crypt.base64 and crypt.base64.decode
            and crypt.base64.decode(CROWN_B64))
        if not data and type(syn)=='table' and syn.crypt and syn.crypt.base64
            and syn.crypt.base64.decode then
            data=syn.crypt.base64.decode(CROWN_B64)
        end
        if not data then
            -- Pure Lua base64 fallback for mobile executors without crypt.
            local alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
            local bits=CROWN_B64:gsub('[^'..alphabet..'=]',''):gsub('.',function(ch)
                if ch=='=' then return '' end
                local n=alphabet:find(ch,1,true)-1
                local str=''
                for i=6,1,-1 do
                    str=str..(n%2^i-n%2^(i-1)>0 and '1' or '0')
                end
                return str
            end)
            data=bits:gsub('%d%d%d%d%d%d%d%d',function(byte)
                return string.char(tonumber(byte,2))
            end)
        end
        if data then
            writefile('folix_premium_crown.png',data)
            crownAsset=assetFn('folix_premium_crown.png')
        end
    end
end)
